//go:build linux && ppc

// Derived from glibc's <utmp.h> for 32-bit PowerPC, not generated by cgo:
// this file is authored rather than -godefs output, and its provenance is
// therefore recorded here instead of in a "Code generated" header.
//
// The struct follows the same shape as host_linux_386.go and preserves the
// field names the shared parser in host_linux.go uses (Type, Pid, Line, ID,
// User, Host, Exit, Session, Tv, Addr_v6). sizeof(utmp) is 0x180 (384), the
// 32-bit glibc size. The ppc64 sibling uses the same 0x180 because glibc pads
// the 64-bit timeval differently.
//
// LIMITATION, deliberate: this is the *glibc* layout. A musl-based 32-bit
// PowerPC Linux (Adélie, the venue this port tests on) defines struct utmpx
// with an extra int pad before ut_session and an extra 4 bytes of tail, so its
// on-disk records are 388 bytes, not 384, and a non-empty /var/run/utmp would
// be misparsed here. That is left as a recorded limitation rather than guessed
// at, because the record size cannot be detected from an empty file. Nothing in
// syncthing's closure calls host.Users*, so no behaviour rests on it today.
package host

const (
	sizeofPtr      = 0x4
	sizeofShort    = 0x2
	sizeofInt      = 0x4
	sizeofLong     = 0x4
	sizeofLongLong = 0x8
	sizeOfUtmp     = 0x180
)

type (
	_C_short     int16 //nolint:revive //FIXME
	_C_int       int32 //nolint:revive //FIXME
	_C_long      int32 //nolint:revive //FIXME
	_C_long_long int64 //nolint:revive //FIXME
)

type utmp struct {
	Type      int16
	Pad_cgo_0 [2]byte //nolint:revive //FIXME
	Pid       int32
	Line      [32]int8
	ID        [4]int8
	User      [32]int8
	Host      [256]int8
	Exit      exit_status
	Session   int32
	Tv        UtTv
	Addr_v6   [4]int32 //nolint:revive //FIXME
	X__unused [20]int8 //nolint:revive //FIXME
}

type exit_status struct { //nolint:revive //FIXME
	Termination int16
	Exit        int16
}

type UtTv struct {
	Sec  int32
	Usec int32
}
